    Transforms the input grid according to the discovered rule:
    For each maximal rectangular region of a non‑zero colour, if the region
    contains any 0-cells, extend each of those 0-cells to a full line
    (column if the region is wider than tall, row if the region is taller
    than wide). The line is drawn only within the region's bounding box.
    """
    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # ---- identify distinct colours (ignoring 0) -----------------
    colours = set()
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != 0:
                colours.add(v)

    # ---- compute bounding box for each colour -------------------
    bounds = {}
    for col in colours:
        bounds[col] = {'min_r': rows, 'max_r': -1,
                       'min_c': cols, 'max_c': -1}

