        for c in range(cols):
            v = grid[r][c]
            if v != 0:
                b = bounds[v]
                if r < b['min_r']:
                    b['min_r'] = r
                if r > b['max_r']:
                    b['max_r'] = r
                if c < b['min_c']:
                    b['min_c'] = c
                if c > b['max_c']:
                    b['max_c'] = c

    # ---- extend zeros inside each region -----------------------
    for col, b in bounds.items():
        min_r, max_r = b['min_r'], b['max_r']
        min_c, max_c = b['min_c'], b['max_c']
        height = max_r - min_r + 1
        width  = max_c - min_c + 1

        if height < width:               # region is wider -> fill columns
            zero_cols = set()
            for r in range(min_r, max_r + 1):
                for c in range(min_c, max_c + 1):
                    if grid[r][c] == 0:
                        zero_cols.add(c)
            for c in zero_cols:
                for r in range(min_r, max_r + 1):
                    grid[r][c] = 0

        elif width < height:             # region is taller -> fill rows
            zero_rows = set()
            for r in range(min_r, max_r + 1):
                for c in range(min_c, max_c + 1):
                    if grid[r][c] == 0:
                        zero_rows.add(r)
            for r in zero_rows:
                for c in range(min_c, max_c + 1):
                    grid[r][c] = 0
        else:
            # square region – nothing to do (not present in the data)
            pass

    return grid

